<?php
require_once __DIR__ . '/modules/blog/blog-service.php';
require_once __DIR__ . '/../includes/auth.php';
requireAdminAuth();
if(!userHasPermission('blog.manage')){http_response_code(403);exit('You do not have permission to manage blog posts.');}
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT)?:null;$post=$id?blogLoad($id):null;if($id&&!$post){http_response_code(404);exit('Post not found.');}
$errors=$_SESSION['blog_form_errors']??[];$values=$_SESSION['blog_form_values']??null;unset($_SESSION['blog_form_errors'],$_SESSION['blog_form_values']);if($values)$post=array_merge($post??[],$values);
$categories=dbConnection()->query('SELECT id,name FROM blog_categories ORDER BY name')->fetch_all(MYSQLI_ASSOC);
$post=$post??['id'=>0,'category_id'=>null,'title'=>'','slug'=>'','excerpt'=>'','content'=>'','featured_image'=>'','status'=>'draft','published_at'=>''];
$date='';if(!empty($post['published_at']))$date=str_replace(' ','T',substr((string)$post['published_at'],0,16));
$pageTitle=$id?'Edit Blog Post':'Create Blog Post';include __DIR__.'/includes/header.php';
?>
<div class="content-wrap"><section class="panel"><form method="post" action="/backend/admin/blog.php" class="cms-form"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(generateCsrfToken(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)($post['id']??0) ?>"><?php foreach($errors as $error): ?><p class="error-message"><?= htmlspecialchars($error,ENT_QUOTES,'UTF-8') ?></p><?php endforeach; ?>
<label>Title<input required maxlength="240" name="title" value="<?= htmlspecialchars((string)$post['title'],ENT_QUOTES,'UTF-8') ?>"></label><label>Slug<input required maxlength="240" name="slug" value="<?= htmlspecialchars((string)$post['slug'],ENT_QUOTES,'UTF-8') ?>"></label><label>Category<select name="category_id"><option value="">Uncategorized</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (string)($post['category_id']??'')===(string)$c['id']?'selected':'' ?>><?= htmlspecialchars($c['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label><label>Excerpt<textarea name="excerpt" rows="3" maxlength="5000"><?= htmlspecialchars((string)$post['excerpt'],ENT_QUOTES,'UTF-8') ?></textarea></label><label>Content<textarea required name="content" rows="14" maxlength="1000000"><?= htmlspecialchars((string)$post['content'],ENT_QUOTES,'UTF-8') ?></textarea><small>Plain text content in this phase.</small></label><label>Featured image reference<input maxlength="500" name="featured_image" value="<?= htmlspecialchars((string)$post['featured_image'],ENT_QUOTES,'UTF-8') ?>"></label><label>Publication date<input type="datetime-local" name="published_at" value="<?= htmlspecialchars($date,ENT_QUOTES,'UTF-8') ?>"></label><label>Status<select name="status"><?php foreach(['draft','published','scheduled','archived'] as $s): ?><option value="<?= $s ?>" <?= $post['status']===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select></label><div class="form-actions"><a class="btn btn-ghost" href="/backend/admin/blog.php">Cancel</a><button class="btn btn-primary">Save post</button></div></form></section></div><?php include __DIR__.'/includes/footer.php'; ?>
